## This configures the minimum required Terraform and provider versions.
## Configure the AWS profile and region specified in the variables as well as default tags.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Name     = "cg-${var.cgid}"
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

resource "aws_secretsmanager_secret" "easy_secret" {
  name                    = "${var.cgid}_easy_secret"
  description             = "This is the final secret for the 'easy' path of the detection_evasion cloudgoat scenario."
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "easy_secret_value" {
  secret_id     = aws_secretsmanager_secret.easy_secret.id
  secret_string = "cg-secret-889877-282341"
}

resource "aws_secretsmanager_secret" "hard_secret" {
  name                    = "${var.cgid}_hard_secret"
  description             = "This is the final secret for the 'hard' path of the detection_evasion cloudgoat scenario."
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "hard_secret_value" {
  secret_id     = aws_secretsmanager_secret.hard_secret.id
  secret_string = "cg-secret-012337-194329"
}

# does the resource below need a a detailed delivery policy for any reason? Might be worth looking into.
resource "aws_sns_topic" "honeytoken_detected" {
  name = "phase1"
}

resource "aws_sns_topic_subscription" "honeytoken_subscription" {
  topic_arn = aws_sns_topic.honeytoken_detected.arn
  protocol  = "email"
  endpoint  = var.user_email
}

resource "aws_sns_topic" "instance_profile_abnormally_used" {
  name = "phase2"
}

resource "aws_sns_topic_subscription" "instance_profile_subscription" {
  topic_arn = aws_sns_topic.instance_profile_abnormally_used.arn
  protocol  = "email"
